import unittest


def 平分(总数, 猫数):
    if 猫数 <= 0:
        raise ValueError("没有猫，分不了喵")
    return 总数 // 猫数


class 平分体检(unittest.TestCase):
    def test_相等(self):
        self.assertEqual(平分(7, 2), 7 // 2)
    def test_为真(self):
        self.assertTrue(平分(7, 2) > 0)
    def test_找得到(self):
        self.assertIn("小鱼干", "一筐小鱼干")
    def test_该拒绝就拒绝(self):
        self.assertRaises(ValueError, 平分, 7, 0)


本子 = unittest.TestResult()
unittest.defaultTestLoader.loadTestsFromTestCase(平分体检).run(本子)
print("体检了", 本子.testsRun, "项")
print("红了", len(本子.failures) + len(本子.errors), "项")
print("全绿喵" if 本子.wasSuccessful() else "有红的喵")

